# -*- coding: utf-8 -*-
import json
from pathlib import Path
p=Path(__file__).parent
all_s=[]
for f in sorted((p/'chunks').glob('chunk-*.json')):all_s+=json.loads(f.read_text())
draft=json.loads((p/'content-draft.json').read_text())['sections']
draft[12]['boundary_hint']=4384.56
draft[17]['boundary_hint']=5743.98
sections=[];start=0
for i,d in enumerate(draft):
 hint=d['boundary_hint'];cut=min([s['start'] for s in all_s if s['start']>=hint],default=5909.376) if i<len(draft)-1 else 5909.376
 ss=[s for s in all_s if start<=s['start']<cut]
 assert ss
 frames=[{'source_type':'pdf_page','path':f'frames/page-{n:03d}.webp','source_label':'官方网页讲义截图汇编（非官方原生 PDF）','source_url':f'https://jyywiki.cn/GSE/2026/slides4.html#/{n}','page':n,'caption':cap} for n,cap in d.get('pages',[])]
 frames +=[{'source_type':'video_frame','path':f'frames/demo-{t}-screen.webp','time':t,'caption':cap+'（右侧屏幕裁切；原始全画幅留存于证据目录。）'} for t,cap in d.get('videos',[])]
 sections.append({'title':d['title'],'start':start,'end':max(cut,max(s['end'] for s in ss)),'source_ids':[s['id'] for s in ss],'paragraphs':d['paragraphs'],'examples':d.get('examples',[]),'editor_notes':d.get('editor_notes',[]),'frames':frames});start=cut
sections[12]['examples']=['整理者复核屏幕递归：n=3 从 A 到 B 需15步，到 C 需21步，均不同于普通汉诺塔的7步。对 n=1..7、目标B/C逐次检查单向移动和大小盘合法性，并用独立广度优先搜索比较最短步数，14组全部一致；这是有限规模验证，不替代一般性最优证明。']
notes={'schema_version':2,'title':'04｜软件仓库管理（2）：修改、并发与从零开始','source_url':'https://www.bilibili.com/video/BV1Q6en6NEUo','limitations':['本课98分29秒；完整阅读20个最终转写块、463个合并句，保留原始导出与全部时间索引。原始转写含错词，正文据上下文、讲义和画面校正，未逐秒人工回听。','完整阅读官方课程正文与25页讲义文字；全部25页图已逐图目视。讲义以当前官网截图汇编PDF冻结，非官方原生PDF，也不标成同秒视频帧。','视频按5分钟网格与演示定点抽帧核对；未逐秒观看。屏幕中的Agent设计和自报结果，不等于本次运行或审计了其项目。','技术校注另核对jj与Git官方文档相关段落；其他课堂职业趋势、商业化和未来工具设想保留为讲师观点。','窄屏浏览器验收记录见 review.json；未做真实手机设备测试。'],'read_chunks':[f'chunk-{i:04d}' for i in range(1,21)],'omitted':[],'summary':['版本管理保存的不只是代码快照，还包括修改身份、演化路径与决策教训；文件齐全并不保证需求、文档、代码和测试之间的关联齐全。','Agent 加速生成以后，工作隔离、任务分解、协调时机、验证和整合必须一起改进。Worktree隔离工作目录，锁协调共享状态，两者都不自动保证正确。','从零开始时，早期提示会把含混意图迅速固定成架构。先用MVP验证真正需要什么，再用真实需求变化检验设计，比一次生成完整信息系统更容易保留选择空间。'],'sections':sections,'self_test':[{'question':'文档、代码、测试都在仓库中，为什么仍会失去可追溯性？','answer':'文件存在不等于它们的语义依赖被记录。链表改树后，若不知道相关文档与测试有哪些，就会形成不一致。','section':2},{'question':'jj 的 change ID 与 commit ID 分别解决什么？','answer':'commit ID标识一个具体提交；change ID通常在重写中延续，用于追踪同一项工作的演化。change是概念，官方模型中它不是独立对象。','section':6},{'question':'worktree解决了哪些并行问题，又留下哪些？','answer':'它隔离工作文件、HEAD和index，共享仓库对象与常规引用；仍需整合提交、处理语义冲突和验证，不提供容器级安全隔离。','section':9},{'question':'“先上锁”为什么不能自动让多Agent开发正确？','answer':'锁范围可能遗漏依赖，参与者可能不遵守协议，持锁工作也可能逻辑错误；仍需读最新状态、验证、快照和恢复策略。','section':11},{'question':'为什么单向汉诺塔不能直接套2^n−1？','answer':'只能沿A→B→C→A移动，最大的盘子可能需经过中间柱，递归结构改变。n=3从A到C的本例是21步。','section':13},{'question':'demo里出现sent或receipt，为什么不能直接宣称真实系统接通？','answer':'画面明确说明外部数据使用fixtures，真实授权和适配器最后一公里未验证。需要区分模拟流程、真实代码与真实外部执行。','section':17},{'question':'怎样判断一个MVP值得做？','answer':'先说清最重要的用户需要和最不确定的假设，再做能产生有效观察的最小版本；功能齐全不等于用户真正需要。','section':18}],'supplements':[{'title':'讲义补充｜“会成长”应能被观察','text':'成长不是只增加日志。可用一个可复核闭环衡量：保存一次明确的偏好或纠正，在下一次相关任务中真正采用，并允许再修正。记忆需要区分长期偏好、暂时目标与已经失效的信息；当前状态、历史和教训各有不同作用。','source_label':'官方课程讲义，课堂未逐项展开','source_url':'https://jyywiki.cn/GSE/2026/lect4.md','pages':[1,19,23]},{'title':'讲义补充｜锁也需要恢复与失败策略','text':'只规定上锁/解锁不够：Agent崩溃后谁释放锁，多个资源如何避免循环等待，读取发生在持锁之前还是之后，都需要约定。大范围锁减少冲突却压缩并行；细粒度锁提高并行却增加依赖管理。依靠所有参与者共同遵守的advisory协议，本身不是正确性证明。','source_label':'官方课程讲义，课堂未逐项展开','source_url':'https://jyywiki.cn/GSE/2026/lect4.md','pages':[15,16]},{'title':'官方文档校注｜jj 的精确定义','text':'glossary说明change是commit随时间演化的概念，只有change ID是commit属性。working-copy说明多数jj命令会把变化写成工作副本的新提交并替换当前修订。正文保留课堂直觉，同时校正“独立change对象”“每字节即时提交”“旧提交立刻抹除”等容易误读的表达。','source_label':'jj 官方 glossary 与 working-copy 文档相关段落，2026-10-02读取','source_url':'https://github.com/jj-vcs/jj/blob/main/docs/working-copy.md'},{'title':'官方文档校注｜worktree 与合并边界','text':'Git官方手册说明linked worktree共享仓库资料，但HEAD、index等为各工作树独立；refs也有特例。Merge保留被合并的历史，并在非快进合并时新增合并提交，不能把冲突解决者的责任问题表述成原作者普遍被改写。','source_label':'Git 官方 git-worktree/git-merge 手册相关段落，2026-10-02读取','source_url':'https://github.com/git/git/blob/master/Documentation/git-worktree.adoc'}]}
(p/'notes.json').write_text(json.dumps(notes,ensure_ascii=False,indent=2));print(len(sections),sum(len(s['frames']) for s in sections),len(all_s))
